// Eleventy config for the Markdown edition of "Lake's Shadow of the MooN".
// See README.md. Everything that is hand-written lives in src/_includes, src/assets and this file;
// the *.md pages and src/_data/{nav,blogs}.json are generated by ../tools/to_markdown.py.
const fs = require("fs");
const path = require("path");
const syntaxHighlight = require("@11ty/eleventy-plugin-syntaxhighlight");
const container = require("markdown-it-container");
const attrs = require("markdown-it-attrs");

// Deploy under a sub path (project pages: https://user.github.io/<repo>/) with PATH_PREFIX=/<repo>/
let PATH_PREFIX = process.env.PATH_PREFIX || "/";
if (!PATH_PREFIX.startsWith("/")) PATH_PREFIX = "/" + PATH_PREFIX;
if (!PATH_PREFIX.endsWith("/")) PATH_PREFIX += "/";

// uploads/ (images, pdf, tex ...) is NOT copied into this project: it is passed through from the mirror.
// Override with UPLOADS_DIR, or put a real ./uploads folder next to this file (takes precedence).
const localUploads = path.join(__dirname, "uploads");
const UPLOADS_DIR = process.env.UPLOADS_DIR
  ? path.resolve(process.env.UPLOADS_DIR)
  : fs.existsSync(localUploads)
    ? localUploads
    : path.resolve(__dirname, "../chihhanlin-weebly/uploads");

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

function weeblyMarkdown(md) {
  md.use(attrs, { leftDelimiter: "{@", rightDelimiter: "}", allowedAttributes: ["class", "style"] });

  // ::::: multicol [gap]  /  :::: col 50% [gap]   ->  the original Weebly multi column table (gap default 15px)
  const gapOf = (info) => (info.trim().split(/\s+/).pop().match(/^\d+$/) || ["15"])[0];
  md.use(container, "multicol", {
    marker: ":",
    validate: (p) => /^multicol(\s+\d+)?$/.test(p.trim()),
    render: (tokens, i) =>
      tokens[i].nesting === 1
        ? '<div><div class="wsite-multicol"><div class="wsite-multicol-table-wrap" style="margin:0 -' + gapOf(tokens[i].info) + 'px;"><table class="wsite-multicol-table"><tbody class="wsite-multicol-tbody"><tr class="wsite-multicol-tr">\n'
        : "</tr></tbody></table></div></div></div>\n",
  });
  md.use(container, "col", {
    marker: ":",
    validate: (p) => /^col\s+[\d.]+%(\s+\d+)?$/.test(p.trim()),
    render: (tokens, i) => {
      if (tokens[i].nesting !== 1) return "</td>\n";
      const parts = tokens[i].info.trim().split(/\s+/);
      return '<td class="wsite-multicol-col" style="width:' + parts[1] + "; padding:0 " + (parts[2] || "15") + 'px;">\n';
    },
  });

  // a paragraph that only holds an image -> Weebly image block (border / alignment via {@.none .left style="..."})
  md.core.ruler.push("weebly_image", (state) => {
    const t = state.tokens;
    for (let i = 0; i < t.length - 2; i++) {
      if (t[i].type === "paragraph_open" && t[i + 1].type === "inline" && t[i + 2].type === "paragraph_close") {
        const ch = t[i + 1].children;
        if (ch && ch.length === 1 && ch[0].type === "image") {
          const im = ch[0];
          const cls = (im.attrGet("class") || "").split(/\s+/);
          const style = im.attrGet("style") || "width:auto;max-width:100%";
          const src = im.attrGet("src");
          const alt = md.renderer.renderInlineAsText(im.children, state.md.options, state.env);
          const border = cls.includes("none") ? "none" : "thin";
          const align = cls.includes("left") ? "left" : "center";
          const tok = new state.Token("html_block", "", 0);
          tok.block = true;
          tok.content =
            `<div><div class="wsite-image wsite-image-border-${border}" style="padding-top:10px;padding-bottom:10px;margin-left:0;margin-right:0;text-align:${align}">\n` +
            `<a href="${esc(src)}" class="glightbox" data-gallery="page">\n` +
            `<img src="${esc(src)}" alt="${esc(alt)}" style="${esc(style)}" />\n</a>\n` +
            `<div style="display:block;font-size:90%">${esc(im.attrGet("title") || "")}</div>\n</div></div>\n`;
          t.splice(i, 3, tok);
        }
      }
    }
  });

  const r = md.renderer.rules;
  r.paragraph_open = (tokens, i) => (tokens[i].hidden ? "" : '<div class="paragraph" style="text-align:left;">');
  r.paragraph_close = (tokens, i) => (tokens[i].hidden ? "" : "</div>\n");
  const defHeading = r.heading_open || ((tokens, i, o, e, s) => s.renderToken(tokens, i, o));
  r.heading_open = (tokens, i, o, e, s) => {
    if (tokens[i].tag === "h2") return '<h2 class="wsite-content-title" style="text-align:left;">';
    return defHeading(tokens, i, o, e, s);
  };
  r.hr = () =>
    '<div><div style="height: 20px; overflow: hidden; width: 100%;"></div>\n<hr class="styled-hr" style="width:100%;">\n<div style="height: 20px; overflow: hidden; width: 100%;"></div></div>\n';
  const defLink = r.link_open || ((tokens, i, o, e, s) => s.renderToken(tokens, i, o));
  r.link_open = (tokens, i, o, e, s) => {
    const href = tokens[i].attrGet("href") || "";
    if (/^https?:\/\//i.test(href)) {
      tokens[i].attrSet("target", "_blank");
      tokens[i].attrSet("rel", "noopener");
    }
    return defLink(tokens, i, o, e, s);
  };
  return md;
}

module.exports = function (eleventyConfig) {
  eleventyConfig.addPlugin(syntaxHighlight);
  eleventyConfig.amendLibrary("md", weeblyMarkdown);

  // theme + vendor files copied verbatim from the mirror by to_markdown.py (urls inside css rely on this layout)
  eleventyConfig.addPassthroughCopy({
    "static/vendor": "vendor",
    "static/files": "files",
    "static/.nojekyll": ".nojekyll",
    "src/assets": "assets",
    "node_modules/glightbox/dist": "assets/glightbox",
    "node_modules/prismjs/themes/prism.css": "assets/prism.css",
  });
  eleventyConfig.addPassthroughCopy({ [UPLOADS_DIR]: "uploads" });

  eleventyConfig.addCollection("blogPosts", (api) => api.getAll().filter((p) => p.data.postId));

  // posts of one blog in blog order, optionally restricted to one month (archive pages)
  eleventyConfig.addFilter("listPosts", (posts, blog, listing, key) =>
    posts
      .filter((p) => p.data.blog === blog && (listing !== "archive" || p.data.monthKey === key))
      .sort((a, b) => a.data.order - b.data.order)
  );
  // non-ascii -> &#N; like the original flyout json
  eleventyConfig.addFilter("entities", (s) =>
    String(s).replace(/[^\x20-\x7e]/g, (c) => "&#" + c.codePointAt(0) + ";")
  );
  eleventyConfig.addFilter("withPrefix", (u) => (u && u.startsWith("/") ? PATH_PREFIX + u.slice(1) : u));
  eleventyConfig.addFilter("topNavJson", (nav) =>
    JSON.stringify(
      nav.map((n) => ({
        id: String(n.id || "").replace(/^pg/, ""),
        title: String(n.title).replace(/[^\x20-\x7e]/g, (c) => "&#" + c.codePointAt(0) + ";"),
        url: n.url ? PATH_PREFIX + n.url.slice(1) : "",
        target: "",
        nav_menu: false,
        nonclickable: !n.url,
      }))
    )
  );
  eleventyConfig.addGlobalData("pathPrefix", PATH_PREFIX);

  // post-process html: sub-path prefix for root-absolute urls, lazy images
  eleventyConfig.addTransform("urls", function (content) {
    if (!(this.page.outputPath || "").endsWith(".html")) return content;
    let out = content.replace(/<img (?![^>]*\bloading=)/g, '<img loading="lazy" ');
    if (PATH_PREFIX !== "/") {
      out = out
        .replace(/(\s(?:href|src|action|data|poster)=")\/(?!\/)/g, "$1" + PATH_PREFIX)
        .replace(/url\((['"]?)\/(?!\/)/g, "url($1" + PATH_PREFIX);
    }
    return out;
  });

  return {
    dir: { input: "src", output: "_site", includes: "_includes", data: "_data" },
    markdownTemplateEngine: false,
    htmlTemplateEngine: "njk",
    templateFormats: ["md", "njk"],
    pathPrefix: PATH_PREFIX,
  };
};
